mapper.update:
UPDATE ma_index_stage s SET call_state = 'CONFIRMED',output_json = #{outputJson},
    output_sha256 = #{outputSha256},request_count = #{requestCount},
    total_tokens = #{totalTokens,jdbcType=BIGINT},confirmed_at = CURRENT_TIMESTAMP
WHERE s.event_id = #{eventId} AND s.phase = #{phase} AND s.ordinal = #{ordinal}
    AND s.call_state = 'CALL_INTENT' AND s.intent_fence = #{fence}
    AND s.account_id = #{accountId} AND s.source_id = #{sourceId}
    AND s.source_version = #{version} AND s.index_revision = #{indexRevision}
    AND s.source_sha256 = #{sourceSha256} AND s.file_ref IS NOT DISTINCT FROM #{fileRef,jdbcType=VARCHAR}
    AND s.input_sha256 = #{inputSha256} AND s.model = #{model}
    AND s.dimensions = #{dimensions} AND s.schema_version = #{schemaVersion}
    AND EXISTS (SELECT 1 FROM ma_index_job j WHERE j.event_id = s.event_id
        AND j.fence = #{fence} AND j.status = 'PROCESSING'
        AND j.lease_until > CURRENT_TIMESTAMP AND j.index_protocol = 'HANDWRITING_METHODS_V1')
    AND EXISTS (SELECT 1 FROM ma_outbox e JOIN ma_source src
        ON src.source_id = e.aggregate_id AND src.account_id = e.account_id
        JOIN ma_source_version v ON v.source_id = src.source_id
            AND v.version = e.aggregate_version
        WHERE e.event_id = s.event_id AND e.account_id = #{accountId}
            AND src.source_id = #{sourceId} AND src.type = 'SAVED_ANSWER'
            AND src.status = 'ACTIVE'
            AND src.current_version = #{version} AND v.status = 'INDEX_PENDING'
            AND v.index_revision = #{indexRevision} AND e.index_revision = #{indexRevision}
            AND v.content_sha256 = #{sourceSha256} AND e.payload_digest = #{sourceSha256}
            AND v.file_ref IS NOT DISTINCT FROM #{fileRef,jdbcType=VARCHAR})

WITH changed AS (
    UPDATE ma_index_stage SET call_state = 'UNKNOWN'
    WHERE event_id = #{eventId} AND phase = #{phase} AND ordinal = #{ordinal}
        AND account_id = #{accountId} AND source_id = #{sourceId}
        AND source_version = #{version} AND index_revision = #{indexRevision}
        AND source_sha256 = #{sourceSha256}
        AND file_ref IS NOT DISTINCT FROM #{fileRef,jdbcType=VARCHAR}
        AND input_sha256 = #{inputSha256} AND model = #{model}
        AND dimensions = #{dimensions} AND schema_version = #{schemaVersion}
        AND call_state = 'CALL_INTENT' AND intent_fence = #{fence}
    RETURNING event_id
) UPDATE ma_index_job SET usage_uncertain = TRUE
    WHERE event_id IN (SELECT event_id FROM changed)

mapper.select:
SELECT COUNT(*) FROM ma_outbox e JOIN ma_source s
    ON s.source_id = e.aggregate_id AND s.account_id = e.account_id
JOIN ma_source_version v ON v.source_id = s.source_id AND v.version = e.aggregate_version
WHERE e.event_id = #{eventId} AND e.account_id = #{accountId}
    AND e.aggregate_id = #{sourceId} AND e.aggregate_version = #{version}
    AND e.index_revision = #{indexRevision} AND e.aggregate_type = 'SOURCE'
    AND e.kind IN ('SOURCE_VERSION_CREATED','SOURCE_REINDEX')
    AND s.status = 'ACTIVE' AND s.current_version = #{version}
    AND v.status = 'INDEX_PENDING' AND v.index_revision = #{indexRevision}
    AND v.content_sha256 = e.payload_digest

SELECT step_id,account_id,run_id,query_sha256,embedding_model,dimensions,call_state,
    embedding::text AS embedding,embedding_requests,embedding_tokens
FROM ma_query_embedding WHERE step_id = #{stepId}

mapper.update:
UPDATE ma_query_embedding SET call_state = 'CONFIRMED',
    embedding = CAST(#{vector} AS vector),embedding_requests = #{requestCount},
    embedding_tokens = #{totalTokens,jdbcType=BIGINT},confirmed_at = CURRENT_TIMESTAMP
WHERE step_id = #{stepId} AND account_id = #{accountId} AND run_id = #{runId}
    AND query_sha256 = #{querySha256} AND embedding_model = #{model}
    AND dimensions = #{dimensions} AND call_state = 'CALL_INTENT'

UPDATE ma_outbox SET status = #{status}
WHERE event_id = #{eventId} AND account_id = #{accountId} AND aggregate_type = 'SOURCE'
    AND status IN ('PENDING','FAILED')

mapper.select:
SELECT COUNT(*) FROM ma_anchor a JOIN ma_source s ON s.source_id = a.source_id
JOIN ma_source_version v ON v.source_id = a.source_id AND v.version = a.version
WHERE s.account_id = #{accountId} AND s.status = 'ACTIVE' AND s.current_version = #{version}
    AND s.type IN ('QUESTION','SAVED_ANSWER','NOTE','TUTOR_REPLY') AND v.status = 'READY'
    AND a.source_id = #{sourceId} AND a.version = #{version} AND a.anchor_id = #{anchorId}
